import 'dart:async';
import 'package:dierb_api_client/dierb_api_client.dart';
import 'package:flutter/material.dart';
class OrderConversationPage extends StatefulWidget{const OrderConversationPage({super.key,required this.orderId});final String orderId;@override State<OrderConversationPage>createState()=>_State();}
class _State extends State<OrderConversationPage>{final api=DierbApi(),text=TextEditingController();List<dynamic>messages=const[];String uid='';bool busy=false;Timer?timer;@override void initState(){super.initState();_start();}Future<void>_start()async{uid=(await api.profile())['id'].toString();await _load();timer=Timer.periodic(const Duration(seconds:5),(_)=>_load());}Future<void>_load()async{try{final v=await api.chatMessages(widget.orderId);if(mounted)setState(()=>messages=v);}catch(_){}}Future<void>_send()async{if(text.text.trim().isEmpty)return;setState(()=>busy=true);try{await api.sendChatMessage(widget.orderId,text.text.trim());text.clear();await _load();}finally{if(mounted)setState(()=>busy=false);}}@override void dispose(){timer?.cancel();api.close();text.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('محادثة الطلب')),body:Column(children:[Expanded(child:messages.isEmpty?const Center(child:Text('ابدأ محادثة آمنة مع أطراف الطلب')):ListView.builder(reverse:true,padding:const EdgeInsets.all(14),itemCount:messages.length,itemBuilder:(_,i){final m=Map<String,dynamic>.from(messages[i]as Map),mine=m['senderId']==uid;return Align(alignment:mine?AlignmentDirectional.centerStart:AlignmentDirectional.centerEnd,child:Card(color:mine?const Color(0xFFDCEFE6):null,child:Padding(padding:const EdgeInsets.all(12),child:Text((m['body']??'').toString()))));})),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:text,decoration:const InputDecoration(hintText:'اكتب رسالة...'))),IconButton.filled(onPressed:busy?null:_send,icon:const Icon(Icons.send_rounded))])))]));}
